if.script:
                // NB: no `import` here — this <script> sits after <entity-find-one> in one compiled actions
                // block, so imports would land mid-script (parse error). Fully-qualify java.math.* instead.
                def bd = { v -> (v == null) ? null : (v as java.math.BigDecimal) }
                def nz = { v -> ((v ?: 0) as java.math.BigDecimal) }
                def _sub = nz(inv.subtotal), _tax = nz(inv.taxAmount)
                def _cgst = bd(inv.cgstAmount), _sgst = bd(inv.sgstAmount), _igst = bd(inv.igstAmount)
                context.hasSplit = (_cgst != null && _cgst.signum() != 0) || (_sgst != null && _sgst.signum() != 0) || (_igst != null && _igst.signum() != 0)
                context.isInterState = (_igst != null && _igst.signum() != 0)

                def gstPct = _sub.signum() > 0 ? _tax.multiply(new java.math.BigDecimal(100)).divide(_sub, 2, java.math.RoundingMode.HALF_UP) : java.math.BigDecimal.ZERO
                def halfPct = gstPct.divide(new java.math.BigDecimal(2), 2, java.math.RoundingMode.HALF_UP)
                context.gstPctStr = gstPct.stripTrailingZeros().toPlainString()
                context.halfPctStr = halfPct.stripTrailingZeros().toPlainString()

                def cur = inv.currencyUomId ?: 'INR'
                def sym = cur == 'INR' ? '₹' : (cur + ' ')
                def money = { v -> sym + zinr.inr(ec.l10n.format(nz(v), '#,##0.00')) }
                context.subtotalFmt = money(inv.subtotal)
                context.taxFmt   = money(inv.taxAmount)
                context.cgstFmt  = money(inv.cgstAmount)
                context.sgstFmt  = money(inv.sgstAmount)
                context.igstFmt  = money(inv.igstAmount)
                context.totalFmt = money(inv.totalAmount)

                def dt = { d -> d == null ? '' : ec.l10n.format(d, 'dd-MMM-yyyy') }
                context.invNo = inv.invoiceNumber ?: inv.saasInvoiceId
                context.invDateStr = dt(inv.invoiceDate)
                context.dueDateStr = dt(inv.dueDate)
                context.periodStr = dt(inv.periodFrom) + ' to ' + dt(inv.periodTo)
                context.statusDesc = ec.entity.find("moqui.basic.StatusItem").condition("statusId", inv.statusId).disableAuthz().one()?.description ?: inv.statusId

                def gstinOf = { pid -> pid ? ec.entity.find("mantle.party.PartyIdentification")
                    .condition("partyId", pid).condition("partyIdTypeEnumId", "PtidGstin").disableAuthz().one()?.idValue : null }
                context.supplierName = ec.entity.find("mantle.party.Organization").condition("partyId", "ZETAERP").disableAuthz().one()?.organizationName ?: "ZetaERP Platform"
                context.supplierGstin = gstinOf("ZETAERP") ?: '— not configured —'
                context.buyerName = tenant?.tenantName ?: inv.tenantId
                context.buyerSub = tenant?.subdomain ?: ''
                context.buyerGstin = gstinOf(tenant?.organizationPartyId) ?: '—'
                context.posStr = inv.placeOfSupply ?: '—'
                context.gstLineLabel = 'GST @ ' + context.gstPctStr + '%' + (inv.placeOfSupply ? ' (POS ' + inv.placeOfSupply + ')' : '')
                context.splitNote = context.hasSplit ? '' :
                    "GST head-split (CGST/SGST vs IGST) appears once ZETAERP's GSTIN + state and the tenant's state are configured; the total tax is correct either way."
